export const getUploadResultUrl = () => {




  return `/api/results/upload`
}

/**
 * Requires staff access JWT. Roles `super_admin`, `medical_records`, `laboratory`, `radiology`.
Laboratory may upload `laboratory` only. Radiology may upload imaging categories.
Multipart field `file` is required. Stored path is application-generated; clients never send filesystem paths.
Supported types PDF/JPEG/PNG. Maximum size 50 MiB (`RESULT_MAX_FILE_BYTES`). Oversize → 400, not 413.

 * @summary Upload a diagnostic result file
 */
export const uploadResult = async (resultUploadInput: ResultUploadInput, options?: RequestInit): Promise<Result> => {
    const formData = new FormData();
formData.append(`file`, resultUploadInput.file);
formData.append(`patientId`, resultUploadInput.patientId.toString())
formData.append(`category`, resultUploadInput.category);
formData.append(`releaseOption`, resultUploadInput.releaseOption);
if(resultUploadInput.scheduledReleaseDate !== undefined) {
 formData.append(`scheduledReleaseDate`, resultUploadInput.scheduledReleaseDate);
 }
if(resultUploadInput.remarks !== undefined) {
 formData.append(`remarks`, resultUploadInput.remarks);
 }
if(resultUploadInput.physicianId !== undefined) {
 formData.append(`physicianId`, resultUploadInput.physicianId.toString())
 }
if(resultUploadInput.assignedPhysicianId !== undefined) {
 formData.append(`assignedPhysicianId`, resultUploadInput.assignedPhysicianId.toString())
 }

  return customFetch<Result>(getUploadResultUrl(),
  {
    ...options,
    method: 'POST'
    ,
    body:
      formData,
  }
);}




