export const getGetPortalCareHistoryUrl = () => {




  return `/api/portal/care-history`
}

/**
 * Requires portal JWT. Identity is derived exclusively from the portal session
(`JWT.patientId`). Client-supplied `patientId` is ignored.

Assembles a bounded timeline from:
- ShanScheduler appointments (read-only; PatientHisId join only)
- ACE_ResultsPortal released results the patient can already access
- ACE_ResultsPortal prescriptions owned by the patient

Source failures are isolated: scheduler unavailability does not clear
results/prescriptions. Deep links are pointers only and must be re-authorized
by destination endpoints. Does not write to ShanScheduler or LiveDB_ACE.

 * @summary Get unified care history for the authenticated patient
 */
export const getPortalCareHistory = async ( options?: RequestInit): Promise<PortalCareHistory> => {

  return customFetch<PortalCareHistory>(getGetPortalCareHistoryUrl(),
  {
    ...options,
    method: 'GET'


  }
);}





